/* SPDX-License-Identifier: AGPL-3.0-or-later */
// ANIMA — la conoscenza di GIOCO di NucleoOS, nelle 5 lingue: come si fa ciò che la console sa fare.
//
// Le abilità di console (console-skills.js) rispondono con i DATI del device; qui ci sono le SPIEGAZIONI:
// tasti durante il gioco, trucchi, Ports e PortMaster, RetroAchievements, netplay, emulatori, PSP e
// Dreamcast... Ogni frase viene dal codice o dai documenti del progetto, non dalla memoria di un modello:
// i percorsi dei menu sono quelli di nucleos-core/src (romwheel.c, syswheel.c, menu.c, guide.c), i tasti
// quelli della Guida, i fatti sugli emulatori quelli provati da nucleos-emu-tune (15/10/2026). Un fatto
// che cambia nel codice va cambiato anche qui: test.mjs controlla che ogni voce abbia le 5 lingue.
//
// Due usi:
//   answer(q, lang)  -> una risposta pronta (forma di /api/anima) se la domanda riguarda una voce, o null
//   handbook()       -> lo stesso sapere, compatto e in inglese, per il prompt dei modelli (cloud, Agenti):
//                       il modello risponde nella lingua dell'utente, ma i fatti restano questi.
// Puro, come console-skills.js.

import { fold } from './console-i18n.js';

// I tasti, scritti una volta: i nomi dei pulsanti non si traducono (sono stampati sulla console).
const HOT = '- **SELECT + START**: {menu}\n- **SELECT + R**: {save}\n- **SELECT + L**: {load}\n- **SELECT + X**: {ra}\n- **SELECT + Y**: {shot}';
const hot = (menu, save, load, ra, shot) => HOT.replace('{menu}', menu).replace('{save}', save).replace('{load}', load).replace('{ra}', ra).replace('{shot}', shot);

// Ogni voce: match (domanda già piegata da fold(), nelle 5 lingue), text {it,en,es,fr,de}, cards facoltative.
export const KB = {
  hotkeys: {
    match: /\b(tasti|combinazion\w*|scorciatoi\w*|hotkeys?|shortcuts?|buttons?|botones|atajos|combinaciones|touches|raccourcis|combinaisons|tasten\w*|tastenkombination\w*)\b.*\b(gioc\w*|game|playing|juego|jugando|jeu|partie|spiel\w*)\b|\b(come|how|como|comment|wie)\b.*\b(esco|uscire|torno al menu|exit|quit|leave|salgo|salir|sortir|quitter|beende|beenden|verlasse|verlassen)\b|\b(screenshot|schermata|captura de pantalla|capture d ecran|bildschirmfoto)\b|\bmenu (di )?retroarch\b|\bretroarch menu\b/,
    text: {
      it: 'Durante un gioco tieni premuto **SELECT** e premi:\n' + hot('torna al menu di NucleoOS', 'salva lo stato', 'carica lo stato', 'menu di RetroArch: opzioni, trucchi, filtri', 'screenshot') +
        '\n\nUscendo, NucleoOS salva sempre anche lo stato automatico: **Continua** riparte da lì. Avanti veloce, volume e luminosità non hanno una combinazione durante il gioco: il volume e la luminosità si regolano dal Centro rapido (tieni premuto SELECT nei menu).',
      en: 'During a game hold **SELECT** and press:\n' + hot('back to the NucleoOS menu', 'save state', 'load state', 'RetroArch menu: options, cheats, filters', 'screenshot') +
        '\n\nWhen you quit, NucleoOS always writes the automatic state too: **Continue** picks up from there. Fast-forward, volume and brightness have no in-game combo: volume and brightness are in the Quick Center (hold SELECT in the menus).',
      es: 'Durante un juego mantén pulsado **SELECT** y pulsa:\n' + hot('volver al menú de NucleoOS', 'guardar el estado', 'cargar el estado', 'menú de RetroArch: opciones, trucos, filtros', 'captura de pantalla') +
        '\n\nAl salir, NucleoOS guarda siempre también el estado automático: **Continuar** sigue desde ahí. Avance rápido, volumen y brillo no tienen combinación durante el juego: volumen y brillo están en el Centro rápido (mantén SELECT en los menús).',
      fr: 'Pendant un jeu, maintiens **SELECT** et appuie sur :\n' + hot('retour au menu de NucleoOS', 'sauvegarder l\'état', 'charger l\'état', 'menu RetroArch : options, codes de triche, filtres', 'capture d\'écran') +
        '\n\nEn quittant, NucleoOS écrit toujours aussi l\'état automatique : **Continuer** reprend de là. Avance rapide, volume et luminosité n\'ont pas de combinaison en jeu : le volume et la luminosité sont dans le Centre rapide (maintiens SELECT dans les menus).',
      de: 'Halte im Spiel **SELECT** gedrückt und drücke:\n' + hot('zurück zum NucleoOS-Menü', 'Zustand speichern', 'Zustand laden', 'RetroArch-Menü: Optionen, Cheats, Filter', 'Bildschirmfoto') +
        '\n\nBeim Beenden schreibt NucleoOS immer auch den automatischen Zustand: **Fortsetzen** macht dort weiter. Vorspulen, Lautstärke und Helligkeit haben keine Tastenkombination im Spiel: Lautstärke und Helligkeit findest du im Schnellzentrum (SELECT in den Menüs gedrückt halten).' },
  },
  resume: {
    match: /\b(continua|riprend\w*|da dove avevo lasciato|resume|carry on|pick up where|continuar|retomar|donde lo deje|continuer|reprendre|la ou je m etais arrete|fortsetzen|weitermachen|wo ich aufgehort)\b.*\b(gioc\w*|game|partita|juego|partida|jeu|partie|spiel)\b/,
    text: {
      it: 'Ogni volta che esci da un gioco NucleoOS ne salva lo stato. Per ripartire da lì:\n- nella lista dei sistemi apri **Continua**: i giochi con uno stato salvato, dal più recente; A riparte subito;\n- oppure, sul gioco, **Y** apre il pannello e **X** riprende;\n- nei menu, tieni premuto **SELECT** (Centro rapido) → continua l\'ultimo gioco.',
      en: 'Every time you leave a game NucleoOS saves its state. To pick up from there:\n- in the systems list open **Continue**: games with a saved state, newest first; A resumes at once;\n- or, on the game, **Y** opens its panel and **X** resumes;\n- in the menus, hold **SELECT** (Quick Center) → continue the last game.',
      es: 'Cada vez que sales de un juego NucleoOS guarda su estado. Para seguir desde ahí:\n- en la lista de sistemas abre **Continuar**: los juegos con estado guardado, del más reciente; A lo retoma al momento;\n- o, sobre el juego, **Y** abre su panel y **X** lo retoma;\n- en los menús, mantén **SELECT** (Centro rápido) → continuar el último juego.',
      fr: 'Chaque fois que tu quittes un jeu, NucleoOS sauvegarde son état. Pour reprendre de là :\n- dans la liste des systèmes, ouvre **Continuer** : les jeux avec un état sauvegardé, du plus récent ; A reprend tout de suite ;\n- ou, sur le jeu, **Y** ouvre son panneau et **X** reprend ;\n- dans les menus, maintiens **SELECT** (Centre rapide) → continuer le dernier jeu.',
      de: 'Jedes Mal, wenn du ein Spiel verlässt, speichert NucleoOS seinen Zustand. Um dort weiterzumachen:\n- öffne in der Systemliste **Fortsetzen**: Spiele mit gespeichertem Zustand, neueste zuerst; A setzt sofort fort;\n- oder drück auf dem Spiel **Y** für sein Panel und dann **X**;\n- in den Menüs **SELECT** gedrückt halten (Schnellzentrum) → letztes Spiel fortsetzen.' },
  },
  saves: {
    text: {
      it: 'I salvataggi stanno sulla scheda dei giochi, accanto alle ROM del loro sistema:\n- il **salvataggio del gioco** (`.srm`) è lo stesso sulla console e nel browser: giochi qui, riprendi là;\n- uscendo da un gioco sulla console si salva anche lo **stato**, e «Continua» riparte da quel punto; durante il gioco SELECT+R salva lo stato e SELECT+L lo ricarica;\n- prima e dopo ogni partita NucleoOS tiene una **copia**: sulla console Y sul gioco → START → **Salvataggi**, nel browser la scheda del gioco nell\'app Console; ogni copia si può rimettere;\n- per una copia di tutto sul PC c\'è **Impostazioni → Backup**.\n\nChiedimi «i salvataggi di …» per vedere quelli di un gioco.',
      en: 'Saves live on the games card, next to their system\'s ROMs:\n- the **game save** (`.srm`) is the same on the console and in the browser: play here, carry on there;\n- leaving a game on the console also saves its **state**, and “Continue” restarts from that point; in game SELECT+R saves the state and SELECT+L loads it;\n- before and after every session NucleoOS keeps a **copy**: on the console Y on the game → START → **Saves**, in the browser the game\'s card in the Console app; any copy can be put back;\n- for a copy of everything on your PC there is **Settings → Backup**.\n\nAsk me “saves of …” to see a game\'s saves.',
      es: 'Las partidas guardadas están en la tarjeta de juegos, junto a las ROM de su sistema:\n- la **partida del juego** (`.srm`) es la misma en la consola y en el navegador: juegas aquí, sigues allí;\n- al salir de un juego en la consola también se guarda el **estado**, y «Continuar» sigue desde ese punto; en el juego SELECT+R guarda el estado y SELECT+L lo carga;\n- antes y después de cada partida NucleoOS guarda una **copia**: en la consola Y sobre el juego → START → **Partidas guardadas**, en el navegador la ficha del juego en la app Consola; cualquier copia se puede restaurar;\n- para una copia de todo en el PC está **Ajustes → Copia de seguridad**.\n\nPregúntame «partidas de …» para ver las de un juego.',
      fr: 'Les sauvegardes sont sur la carte des jeux, à côté des ROM de leur système :\n- la **sauvegarde du jeu** (`.srm`) est la même sur la console et dans le navigateur : tu joues ici, tu continues là-bas ;\n- en quittant un jeu sur la console, l\'**état** est aussi sauvegardé, et « Continuer » reprend de ce point ; en jeu SELECT+R sauvegarde l\'état et SELECT+L le charge ;\n- avant et après chaque partie NucleoOS garde une **copie** : sur la console Y sur le jeu → START → **Sauvegardes**, dans le navigateur la fiche du jeu dans l\'app Console ; chaque copie peut être remise ;\n- pour une copie de tout sur le PC, il y a **Réglages → Sauvegarde**.\n\nDemande-moi « sauvegardes de … » pour voir celles d\'un jeu.',
      de: 'Spielstände liegen auf der Spielekarte, neben den ROMs ihres Systems:\n- der **Spielspeicher** (`.srm`) ist auf der Konsole und im Browser derselbe: hier spielen, dort weitermachen;\n- beim Verlassen eines Spiels auf der Konsole wird auch der **Zustand** gespeichert, und „Fortsetzen“ macht dort weiter; im Spiel speichert SELECT+R den Zustand und SELECT+L lädt ihn;\n- vor und nach jeder Runde behält NucleoOS eine **Kopie**: auf der Konsole Y auf dem Spiel → START → **Spielstände**, im Browser der Steckbrief des Spiels in der App Konsole; jede Kopie lässt sich zurückholen;\n- für eine Kopie von allem auf dem PC gibt es **Einstellungen → Backup**.\n\nFrag mich „Spielstände von …“, um die eines Spiels zu sehen.' },
    cards: [{ kind: 'app', arg: 'console', title: 'Console', sub: '' }],
  },
  addroms: {
    text: {
      it: 'Le ROM vanno nella scheda dei giochi, una cartella per sistema (per esempio `roms/gba`, `roms/snes`, `roms/psx`). Tre modi:\n- **dal browser**: apri l\'app File, entra in ROMs e nella cartella del sistema, e trascinaci i file;\n- **col cavo USB**: sulla console apri **Disco USB** e la scheda compare sul PC come una chiavetta;\n- **a console spenta**: metti la scheda nel PC e copia nelle stesse cartelle.\n\nLa libreria si aggiorna da sola. Alcuni sistemi (PlayStation, Neo Geo, Sega CD…) chiedono anche un BIOS: chiedimi «mi manca qualche BIOS?».',
      en: 'ROMs go on the games card, one folder per system (for example `roms/gba`, `roms/snes`, `roms/psx`). Three ways:\n- **from the browser**: open the File app, go to ROMs and the system\'s folder, and drop the files there;\n- **over the USB cable**: on the console open **USB Drive** and the card shows up on the PC like a stick;\n- **with the console off**: put the card in the PC and copy into the same folders.\n\nThe library updates by itself. Some systems (PlayStation, Neo Geo, Sega CD…) also need a BIOS: ask me “am I missing any BIOS?”.',
      es: 'Las ROM van en la tarjeta de juegos, una carpeta por sistema (por ejemplo `roms/gba`, `roms/snes`, `roms/psx`). Tres formas:\n- **desde el navegador**: abre la app Archivos, entra en ROMs y en la carpeta del sistema, y arrastra ahí los archivos;\n- **con el cable USB**: en la consola abre **Disco USB** y la tarjeta aparece en el PC como un pendrive;\n- **con la consola apagada**: pon la tarjeta en el PC y copia en las mismas carpetas.\n\nLa biblioteca se actualiza sola. Algunos sistemas (PlayStation, Neo Geo, Sega CD…) también piden una BIOS: pregúntame «¿me falta alguna BIOS?».',
      fr: 'Les ROM vont sur la carte des jeux, un dossier par système (par exemple `roms/gba`, `roms/snes`, `roms/psx`). Trois façons :\n- **depuis le navigateur** : ouvre l\'app Fichiers, entre dans ROMs puis dans le dossier du système, et glisse-y les fichiers ;\n- **avec le câble USB** : sur la console ouvre **Disque USB** et la carte apparaît sur le PC comme une clé ;\n- **console éteinte** : mets la carte dans le PC et copie dans les mêmes dossiers.\n\nLa bibliothèque se met à jour toute seule. Certains systèmes (PlayStation, Neo Geo, Sega CD…) demandent aussi un BIOS : demande-moi « il me manque un BIOS ? ».',
      de: 'ROMs gehören auf die Spielekarte, ein Ordner pro System (zum Beispiel `roms/gba`, `roms/snes`, `roms/psx`). Drei Wege:\n- **im Browser**: öffne die App Dateien, geh in ROMs und den Ordner des Systems und zieh die Dateien hinein;\n- **per USB-Kabel**: öffne auf der Konsole **USB-Laufwerk**, dann erscheint die Karte am PC wie ein Stick;\n- **bei ausgeschalteter Konsole**: steck die Karte in den PC und kopier in dieselben Ordner.\n\nDie Bibliothek aktualisiert sich von selbst. Manche Systeme (PlayStation, Neo Geo, Sega CD…) brauchen auch ein BIOS: Frag mich „fehlt mir ein BIOS?“.' },
    cards: [{ kind: 'app', arg: 'file-commander', title: 'File', sub: '' }],
  },
  cheats_help: {
    text: {
      it: 'I trucchi vengono dal database ufficiale di libretro e li applica **RetroArch sulla console**, dal **prossimo avvio** del gioco (anche lanciato dal browser con «Sulla console»); il player del browser non li usa.\n- **Sulla console**: sul gioco Y → START → **Trucchi**; A accende/spegne, L1/R1 sfogliano, B salva. Se il database manca, Y lo scarica (serve il WiFi).\n- **Nel browser**: app Console → scheda del gioco → Trucchi.\n- **Con me**: «trucchi per Doom», «attiva il trucco vite infinite in Contra», «disattiva i trucchi di Contra».\n\nCon RetroAchievements in modalità hardcore RetroArch non applica trucchi.',
      en: 'Cheats come from the official libretro database and are applied by **RetroArch on the console**, from the game\'s **next start** (also when launched from the browser with “On the console”); the browser player does not use them.\n- **On the console**: on the game Y → START → **Cheats**; A toggles, L1/R1 page, B saves. If the database is missing, Y downloads it (needs WiFi).\n- **In the browser**: Console app → the game\'s card → Cheats.\n- **With me**: “cheats for Doom”, “enable the infinite lives cheat in Contra”, “disable Contra\'s cheats”.\n\nWith RetroAchievements in hardcore mode RetroArch applies no cheats.',
      es: 'Los trucos vienen de la base de datos oficial de libretro y los aplica **RetroArch en la consola**, desde el **próximo arranque** del juego (también lanzado desde el navegador con «En la consola»); el reproductor del navegador no los usa.\n- **En la consola**: sobre el juego Y → START → **Trucos**; A activa/desactiva, L1/R1 pasan página, B guarda. Si falta la base de datos, Y la descarga (hace falta WiFi).\n- **En el navegador**: app Consola → ficha del juego → Trucos.\n- **Conmigo**: «trucos de Doom», «activa el truco vidas infinitas en Contra», «desactiva los trucos de Contra».\n\nCon RetroAchievements en modo hardcore RetroArch no aplica trucos.',
      fr: 'Les codes de triche viennent de la base officielle de libretro et c\'est **RetroArch sur la console** qui les applique, dès le **prochain démarrage** du jeu (même lancé depuis le navigateur avec « Sur la console ») ; le lecteur du navigateur ne les utilise pas.\n- **Sur la console** : sur le jeu Y → START → **Codes de triche** ; A active/désactive, L1/R1 tournent les pages, B enregistre. Si la base manque, Y la télécharge (WiFi nécessaire).\n- **Dans le navigateur** : app Console → fiche du jeu → Codes de triche.\n- **Avec moi** : « codes de triche pour Doom », « active le code vies infinies dans Contra », « désactive les codes de Contra ».\n\nAvec RetroAchievements en mode hardcore, RetroArch n\'applique aucun code.',
      de: 'Cheats kommen aus der offiziellen libretro-Datenbank und werden von **RetroArch auf der Konsole** angewendet, ab dem **nächsten Start** des Spiels (auch wenn es im Browser mit „Auf der Konsole“ gestartet wird); der Browser-Player nutzt sie nicht.\n- **Auf der Konsole**: auf dem Spiel Y → START → **Cheats**; A schaltet um, L1/R1 blättern, B speichert. Fehlt die Datenbank, lädt Y sie herunter (WLAN nötig).\n- **Im Browser**: App Konsole → Steckbrief des Spiels → Cheats.\n- **Mit mir**: „Cheats für Doom“, „aktiviere den Cheat unendliche Leben in Contra“, „deaktiviere die Cheats von Contra“.\n\nMit RetroAchievements im Hardcore-Modus wendet RetroArch keine Cheats an.' },
  },
  quick: {
    match: /\b(centro rapido|quick center|centro rapido|centre rapide|schnellzentrum|schnellmenu)\b|\b(come|how|como|comment|wie)\b.*\b(volume|luminosita|brightness|volumen|brillo|luminosite|lautstarke|helligkeit)\b/,
    text: {
      it: 'Il **Centro rapido**: nei menu di NucleoOS tieni premuto **SELECT** per mezzo secondo. Da lì: continua l\'ultimo gioco, vai a Giochi, Musica, WiFi o Sistema, spegni; e poi volume, luminosità, rete e schermo spento.',
      en: 'The **Quick Center**: in the NucleoOS menus hold **SELECT** for half a second. From there: continue the last game, jump to Games, Music, WiFi or System, power off; then volume, brightness, network and screen off.',
      es: 'El **Centro rápido**: en los menús de NucleoOS mantén **SELECT** medio segundo. Desde ahí: continuar el último juego, ir a Juegos, Música, WiFi o Sistema, apagar; y además volumen, brillo, red y pantalla apagada.',
      fr: 'Le **Centre rapide** : dans les menus de NucleoOS, maintiens **SELECT** une demi-seconde. De là : continuer le dernier jeu, aller à Jeux, Musique, WiFi ou Système, éteindre ; puis volume, luminosité, réseau et écran éteint.',
      de: 'Das **Schnellzentrum**: Halte in den NucleoOS-Menüs **SELECT** eine halbe Sekunde gedrückt. Von dort: letztes Spiel fortsetzen, zu Spiele, Musik, WLAN oder System springen, ausschalten; dazu Lautstärke, Helligkeit, Netzwerk und Bildschirm aus.' },
  },
  ports: {
    match: /\b(port|ports)\b/,
    text: {
      it: 'I **Ports** sono giochi nativi e conversioni (Doom, Quake, giochi indie…): ognuno è uno script `.sh` nella cartella `ports/` della scheda dei giochi; nomi e immagini vengono da `ports/gamelist.xml` se c\'è.\n- **Ports** (scheda Giochi): una ruota come quella dei giochi; A avvia, X preferito, START cerca, SELECT solo i preferiti.\n- **PortMaster** (scheda Giochi): il negozio dei port, per installarli e aggiornarli; parte come un gioco e al ritorno i nuovi port sono nella ruota.\n- Alcuni port servono a NucleoOS stesso: **Install-NucleoOS** (installa e reinstalla), **NucleoOS-Canale-SD** (diagnosi senza rete né cavo).\n\nChiedimi «quali port ho?» per l\'elenco.',
      en: '**Ports** are native games and conversions (Doom, Quake, indie games…): each one is a `.sh` script in the `ports/` folder of the games card; names and pictures come from `ports/gamelist.xml` when present.\n- **Ports** (Games tab): a wheel like the game one; A launches, X favourite, START searches, SELECT favourites only.\n- **PortMaster** (Games tab): the port store, to install and update them; it starts like a game and when you come back the new ports are on the wheel.\n- Some ports serve NucleoOS itself: **Install-NucleoOS** (install and reinstall), **NucleoOS-Canale-SD** (diagnosis with no network or cable).\n\nAsk me “which ports do I have?” for the list.',
      es: 'Los **Ports** son juegos nativos y conversiones (Doom, Quake, juegos indie…): cada uno es un script `.sh` en la carpeta `ports/` de la tarjeta de juegos; nombres e imágenes vienen de `ports/gamelist.xml` si existe.\n- **Ports** (pestaña Juegos): una rueda como la de los juegos; A lanza, X favorito, START busca, SELECT solo favoritos.\n- **PortMaster** (pestaña Juegos): la tienda de ports, para instalarlos y actualizarlos; arranca como un juego y al volver los nuevos ports están en la rueda.\n- Algunos ports sirven al propio NucleoOS: **Install-NucleoOS** (instala y reinstala), **NucleoOS-Canale-SD** (diagnóstico sin red ni cable).\n\nPregúntame «¿qué ports tengo?» para la lista.',
      fr: 'Les **Ports** sont des jeux natifs et des portages (Doom, Quake, jeux indé…) : chacun est un script `.sh` dans le dossier `ports/` de la carte des jeux ; noms et images viennent de `ports/gamelist.xml` s\'il existe.\n- **Ports** (onglet Jeux) : une roue comme celle des jeux ; A lance, X favori, START cherche, SELECT favoris seulement.\n- **PortMaster** (onglet Jeux) : la boutique des ports, pour les installer et les mettre à jour ; il démarre comme un jeu et au retour les nouveaux ports sont sur la roue.\n- Certains ports servent à NucleoOS lui-même : **Install-NucleoOS** (installe et réinstalle), **NucleoOS-Canale-SD** (diagnostic sans réseau ni câble).\n\nDemande-moi « quels ports j\'ai ? » pour la liste.',
      de: '**Ports** sind native Spiele und Umsetzungen (Doom, Quake, Indie-Spiele…): Jeder ist ein `.sh`-Skript im Ordner `ports/` der Spielekarte; Namen und Bilder kommen aus `ports/gamelist.xml`, falls vorhanden.\n- **Ports** (Reiter Spiele): ein Rad wie bei den Spielen; A startet, X Favorit, START sucht, SELECT nur Favoriten.\n- **PortMaster** (Reiter Spiele): der Port-Store zum Installieren und Aktualisieren; er startet wie ein Spiel, und danach stehen die neuen Ports im Rad.\n- Einige Ports dienen NucleoOS selbst: **Install-NucleoOS** (installieren und neu installieren), **NucleoOS-Canale-SD** (Diagnose ohne Netz und Kabel).\n\nFrag mich „welche Ports habe ich?“ für die Liste.' },
  },
  portmaster: {
    match: /\bport ?master\b/,
    text: {
      it: '**PortMaster** è nella scheda Giochi: è il negozio dei port, per installarne di nuovi e aggiornarli (serve il WiFi). Parte come un gioco: NucleoOS si chiude e torna quando esci, e i port installati compaiono nella ruota **Ports**. Molti port commerciali chiedono i file del gioco originale: PortMaster dice quali e dove copiarli.',
      en: '**PortMaster** is in the Games tab: it\'s the port store, to install new ports and update them (needs WiFi). It starts like a game: NucleoOS closes and comes back when you exit, and installed ports show up in the **Ports** wheel. Many commercial ports need the original game\'s files: PortMaster says which ones and where to copy them.',
      es: '**PortMaster** está en la pestaña Juegos: es la tienda de ports, para instalar nuevos y actualizarlos (hace falta WiFi). Arranca como un juego: NucleoOS se cierra y vuelve al salir, y los ports instalados aparecen en la rueda **Ports**. Muchos ports comerciales piden los archivos del juego original: PortMaster dice cuáles y dónde copiarlos.',
      fr: '**PortMaster** est dans l\'onglet Jeux : c\'est la boutique des ports, pour en installer de nouveaux et les mettre à jour (WiFi nécessaire). Il démarre comme un jeu : NucleoOS se ferme et revient quand tu quittes, et les ports installés apparaissent dans la roue **Ports**. Beaucoup de ports commerciaux demandent les fichiers du jeu original : PortMaster dit lesquels et où les copier.',
      de: '**PortMaster** ist im Reiter Spiele: der Port-Store, um neue Ports zu installieren und zu aktualisieren (WLAN nötig). Er startet wie ein Spiel: NucleoOS schließt sich und kommt beim Beenden zurück, und installierte Ports erscheinen im Rad **Ports**. Viele kommerzielle Ports brauchen die Dateien des Originalspiels: PortMaster sagt, welche und wohin.' },
  },
  ra: {
    match: /\b(retro ?achievements?|achievements?|obiettivi|trofei|logros|trofeos|succes|trophees|erfolge|trophaen|hardcore)\b/,
    text: {
      it: '**RetroAchievements** si collega sulla console: nella lista dei sistemi premi **Y** → riga «RetroAchievements», scrivi nome utente e password. NucleoOS scambia subito la password con un token e non la conserva; nome vuoto = esci. Da lì in poi ogni gioco RetroArch parte con gli obiettivi attivi.\nNello stesso menu c\'è **RA hardcore**: niente stati salvati, niente riavvolgimento e niente trucchi, come vuole la modalità hardcore.',
      en: '**RetroAchievements** is set up on the console: in the systems list press **Y** → the “RetroAchievements” row, type username and password. NucleoOS swaps the password for a token straight away and never stores it; empty username = sign out. From then on every RetroArch game starts with achievements on.\nThe same menu has **RA hardcore**: no save states, no rewind and no cheats, as hardcore mode requires.',
      es: '**RetroAchievements** se configura en la consola: en la lista de sistemas pulsa **Y** → fila «RetroAchievements», escribe usuario y contraseña. NucleoOS cambia enseguida la contraseña por un token y no la guarda; usuario vacío = cerrar sesión. Desde entonces cada juego de RetroArch arranca con los logros activos.\nEn el mismo menú está **RA hardcore**: sin estados guardados, sin rebobinado y sin trucos, como exige el modo hardcore.',
      fr: '**RetroAchievements** se configure sur la console : dans la liste des systèmes appuie sur **Y** → ligne « RetroAchievements », saisis identifiant et mot de passe. NucleoOS échange aussitôt le mot de passe contre un jeton et ne le garde pas ; identifiant vide = déconnexion. Ensuite chaque jeu RetroArch démarre avec les succès actifs.\nLe même menu propose **RA hardcore** : pas d\'états sauvegardés, pas de retour arrière et pas de codes de triche, comme l\'exige le mode hardcore.',
      de: '**RetroAchievements** richtest du auf der Konsole ein: in der Systemliste **Y** → Zeile „RetroAchievements“, Benutzername und Passwort eingeben. NucleoOS tauscht das Passwort sofort gegen ein Token und speichert es nicht; leerer Name = abmelden. Danach startet jedes RetroArch-Spiel mit aktiven Erfolgen.\nIm selben Menü gibt es **RA hardcore**: keine Savestates, kein Zurückspulen und keine Cheats, wie es der Hardcore-Modus verlangt.' },
  },
  emulator: {
    match: /\b(cambi\w*|scegli\w*|change|choose|switch|cambiar|elegir|changer|choisir|wechseln|andern|auswahlen)\b.*\b(emulator\w*|core|emulador|emulateur)\b|\b(opzioni (dell )?emulatore|emulator options|opciones del emulador|options de l emulateur|emulatoroptionen|riavvolg\w*|rewind|rebobinar|retour arriere|zuruckspulen|integer scaling|scala intera)\b/,
    text: {
      it: 'L\'emulatore (il «core») si sceglie in due punti:\n- **per un sistema**: nella lista dei sistemi premi **Y** → **Emulatore**;\n- **per un solo gioco**: sul gioco premi **Y** e poi **sinistra/destra**; la scelta resta in `nucleos-cores.txt` nella cartella del sistema.\nLe **opzioni dell\'emulatore** (riavvolgimento, stato automatico salvato e caricato, scala intera) sono in Y → Opzioni emulatore per il sistema, o sul gioco Y → START → Opzioni emulatore (questo gioco). Chiedimi «che emulatore usa la SNES?» per vedere quello attuale.',
      en: 'The emulator (the “core”) is chosen in two places:\n- **for a system**: in the systems list press **Y** → **Emulator**;\n- **for one game**: on the game press **Y** then **left/right**; the choice is kept in `nucleos-cores.txt` in the system\'s folder.\nThe **emulator options** (rewind, auto-save and auto-load state, integer scaling) are in Y → Emulator options for the system, or on the game Y → START → Emulator options (this game). Ask me “which emulator does the SNES use?” to see the current one.',
      es: 'El emulador (el «core») se elige en dos sitios:\n- **para un sistema**: en la lista de sistemas pulsa **Y** → **Emulador**;\n- **para un solo juego**: sobre el juego pulsa **Y** y luego **izquierda/derecha**; la elección queda en `nucleos-cores.txt` en la carpeta del sistema.\nLas **opciones del emulador** (rebobinado, estado automático al salir y al entrar, escala entera) están en Y → Opciones del emulador para el sistema, o sobre el juego Y → START → Opciones del emulador (este juego). Pregúntame «¿qué emulador usa la SNES?» para ver el actual.',
      fr: 'L\'émulateur (le « core ») se choisit à deux endroits :\n- **pour un système** : dans la liste des systèmes appuie sur **Y** → **Émulateur** ;\n- **pour un seul jeu** : sur le jeu appuie sur **Y** puis **gauche/droite** ; le choix reste dans `nucleos-cores.txt` dans le dossier du système.\nLes **options de l\'émulateur** (retour arrière, état automatique sauvegardé et chargé, mise à l\'échelle entière) sont dans Y → Options de l\'émulateur pour le système, ou sur le jeu Y → START → Options de l\'émulateur (ce jeu). Demande-moi « quel émulateur utilise la SNES ? » pour voir l\'actuel.',
      de: 'Den Emulator (den „Core“) wählst du an zwei Stellen:\n- **für ein System**: in der Systemliste **Y** → **Emulator**;\n- **für ein einzelnes Spiel**: auf dem Spiel **Y**, dann **links/rechts**; die Wahl steht in `nucleos-cores.txt` im Ordner des Systems.\nDie **Emulatoroptionen** (Zurückspulen, Zustand automatisch speichern und laden, ganzzahlige Skalierung) findest du unter Y → Emulatoroptionen für das System oder auf dem Spiel Y → START → Emulatoroptionen (dieses Spiel). Frag mich „welchen Emulator nutzt das SNES?“, um den aktuellen zu sehen.' },
  },
  netplay: {
    match: /\b(netplay|multigiocatore online|giocare online|in rete con|play online|online multiplayer|juego en red|jugar en linea|jouer en ligne|en reseau|online spielen|im netzwerk spielen|lan)\b/,
    text: {
      it: 'Il **netplay** unisce due console NucleoOS sulla stessa rete: sul gioco premi **Y**, poi **L** per ospitare una partita o **R** per unirti; la lista mostra le partite ospitate dalle altre console in rete. Chi si unisce senza la ROM la riceve da chi ospita. Lo stick premuto (R3) apre la scheda del multigiocatore.',
      en: '**Netplay** links two NucleoOS consoles on the same network: on the game press **Y**, then **L** to host a game or **R** to join one; the list shows games hosted by other consoles on the network. A guest without the ROM gets it from the host. Clicking the stick (R3) opens the multiplayer sheet.',
      es: 'El **netplay** une dos consolas NucleoOS en la misma red: sobre el juego pulsa **Y**, luego **L** para alojar una partida o **R** para unirte; la lista muestra las partidas alojadas por otras consolas de la red. Quien se une sin la ROM la recibe del anfitrión. Pulsar el stick (R3) abre la ficha multijugador.',
      fr: 'Le **netplay** relie deux consoles NucleoOS sur le même réseau : sur le jeu appuie sur **Y**, puis **L** pour héberger une partie ou **R** pour en rejoindre une ; la liste montre les parties hébergées par les autres consoles du réseau. Un invité sans la ROM la reçoit de l\'hôte. Cliquer le stick (R3) ouvre la fiche multijoueur.',
      de: '**Netplay** verbindet zwei NucleoOS-Konsolen im selben Netz: auf dem Spiel **Y**, dann **L**, um ein Spiel zu hosten, oder **R**, um beizutreten; die Liste zeigt die Spiele, die andere Konsolen im Netz hosten. Wer ohne ROM beitritt, bekommt sie vom Host. Ein Klick auf den Stick (R3) öffnet das Mehrspieler-Blatt.' },
  },
  favorites: {
    match: /\b(preferit\w*|favorit\w*|favourites?|favorites?|favoritos?|favoris?|collezion\w*|collections?|colecciones|coleccion|sammlung\w*)\b/,
    text: {
      it: '**Preferiti e collezioni**: sul gioco **X** lo aggiunge ai Preferiti; **Y** e poi **SELECT** lo mette in una tua collezione. Nella lista dei sistemi trovi anche **Continua** (giochi con uno stato salvato), **Recenti** e **Preferiti**. Nei Ports X segna il preferito e SELECT mostra solo quelli.',
      en: '**Favourites and collections**: on the game **X** adds it to Favourites; **Y** then **SELECT** puts it in one of your collections. The systems list also has **Continue** (games with a saved state), **Recent** and **Favourites**. In Ports X marks a favourite and SELECT shows only those.',
      es: '**Favoritos y colecciones**: sobre el juego **X** lo añade a Favoritos; **Y** y luego **SELECT** lo pone en una de tus colecciones. En la lista de sistemas también están **Continuar** (juegos con estado guardado), **Recientes** y **Favoritos**. En Ports X marca favorito y SELECT muestra solo esos.',
      fr: '**Favoris et collections** : sur le jeu, **X** l\'ajoute aux Favoris ; **Y** puis **SELECT** le met dans une de tes collections. La liste des systèmes a aussi **Continuer** (jeux avec un état sauvegardé), **Récents** et **Favoris**. Dans Ports, X marque un favori et SELECT n\'affiche que ceux-là.',
      de: '**Favoriten und Sammlungen**: auf dem Spiel fügt **X** es den Favoriten hinzu; **Y** und dann **SELECT** legt es in eine deiner Sammlungen. In der Systemliste gibt es auch **Fortsetzen** (Spiele mit gespeichertem Zustand), **Zuletzt** und **Favoriten**. In Ports markiert X einen Favoriten und SELECT zeigt nur diese.' },
  },
  scrape: {
    match: /\b(scrap\w*|copertin\w*|box ?art|covers?|portadas?|caratulas?|jaquettes?|pochettes?|cover\w*|immagini dei giochi|game images|imagenes de los juegos|images des jeux|spielbilder)\b/,
    text: {
      it: 'Copertine, descrizioni, anno e genere li scrive lo **scraper**: nella lista dei sistemi premi **Y** → **Scrape** (il sistema) o **Scrape all** (tutti; serve il WiFi). Se un dato è sbagliato correggilo a mano: sul gioco Y → START → Nome, Genere, Anno, Voto; le tue correzioni restano anche dopo un nuovo scrape.',
      en: 'Covers, descriptions, year and genre are written by the **scraper**: in the systems list press **Y** → **Scrape** (that system) or **Scrape all** (every system; needs WiFi). If something is wrong, fix it by hand: on the game Y → START → Name, Genre, Year, Rating; your fixes survive a new scrape.',
      es: 'Portadas, descripciones, año y género los escribe el **scraper**: en la lista de sistemas pulsa **Y** → **Scrape** (ese sistema) o **Scrape all** (todos; hace falta WiFi). Si un dato está mal corrígelo a mano: sobre el juego Y → START → Nombre, Género, Año, Valoración; tus correcciones se mantienen tras un nuevo scrape.',
      fr: 'Jaquettes, descriptions, année et genre sont écrits par le **scraper** : dans la liste des systèmes appuie sur **Y** → **Scrape** (ce système) ou **Scrape all** (tous ; WiFi nécessaire). Si une info est fausse, corrige-la à la main : sur le jeu Y → START → Nom, Genre, Année, Note ; tes corrections restent après un nouveau scrape.',
      de: 'Cover, Beschreibungen, Jahr und Genre schreibt der **Scraper**: in der Systemliste **Y** → **Scrape** (dieses System) oder **Scrape all** (alle; WLAN nötig). Ist etwas falsch, korrigier es von Hand: auf dem Spiel Y → START → Name, Genre, Jahr, Bewertung; deine Korrekturen überleben einen neuen Scrape.' },
  },
  lowbat: {
    match: /\b(batteria (scarica|bassa)|low battery|bateria (baja|descargada)|batterie (faible|vide)|akku (leer|schwach))\b.*\b(gioc\w*|game|juego|jeu|spiel\w*|salv\w*|save|guard\w*|sauv\w*|speich\w*)\b|\b(perdo|perdere|lose|losing|pierdo|perder|perds|perdre|verliere|verlieren)\b.*\b(salvataggi\w*|saves?|partidas?|sauvegardes?|spielstande?)\b/,
    text: {
      it: 'Con la batteria che si scarica durante un gioco non perdi niente: sotto il **5%** NucleoOS chiude il gioco come faresti tu (RetroArch scrive lo stato automatico) e spegne la console. Nei menu avvisa al 15% e al 10%, e al 5% conta 30 secondi prima di spegnere. In carica non succede nulla. Sulle console che non leggono la batteria (K36) questa protezione non c\'è. In più, prima e dopo ogni partita resta una copia del salvataggio.',
      en: 'If the battery runs down during a game you lose nothing: below **5%** NucleoOS quits the game the way you would (RetroArch writes the automatic state) and powers off. In the menus it warns at 15% and 10%, and at 5% counts down 30 seconds before switching off. Nothing happens while charging. Consoles that can\'t read their battery (K36) don\'t get this protection. On top of that, a copy of the save is kept before and after every session.',
      es: 'Si la batería se agota durante un juego no pierdes nada: por debajo del **5 %** NucleoOS cierra el juego como lo harías tú (RetroArch escribe el estado automático) y apaga la consola. En los menús avisa al 15 % y al 10 %, y al 5 % cuenta 30 segundos antes de apagar. Cargando no pasa nada. Las consolas que no leen la batería (K36) no tienen esta protección. Además, antes y después de cada partida queda una copia de la partida guardada.',
      fr: 'Si la batterie se vide pendant un jeu, tu ne perds rien : sous **5 %** NucleoOS quitte le jeu comme tu le ferais (RetroArch écrit l\'état automatique) et éteint la console. Dans les menus, il prévient à 15 % et 10 %, et à 5 % compte 30 secondes avant d\'éteindre. En charge, rien ne se passe. Les consoles qui ne lisent pas leur batterie (K36) n\'ont pas cette protection. En plus, une copie de la sauvegarde est gardée avant et après chaque partie.',
      de: 'Wenn der Akku im Spiel leer wird, verlierst du nichts: unter **5 %** beendet NucleoOS das Spiel so, wie du es tun würdest (RetroArch schreibt den automatischen Zustand), und schaltet aus. In den Menüs warnt es bei 15 % und 10 % und zählt bei 5 % 30 Sekunden bis zum Ausschalten herunter. Beim Laden passiert nichts. Konsolen, die ihren Akku nicht lesen können (K36), haben diesen Schutz nicht. Außerdem bleibt vor und nach jeder Runde eine Kopie des Spielstands.' },
  },
  browser: {
    match: /\b(giocare|gioco|giochi|play|games?|jugar|juegos?|jouer|jeux|spielen|spiele)\b.*\b(nel browser|dal browser|dal pc|dal telefono|in the browser|from the browser|on (my|the) pc|on my phone|en el navegador|desde el pc|desde el movil|dans le navigateur|depuis le pc|sur mon telephone|im browser|vom pc|am pc|auf dem handy)\b|\b(remote play|gioco remoto|juego remoto|jeu a distance|fernspielen|nucleolink|streaming)\b/,
    text: {
      it: 'Dal browser (sulla stessa rete, o col cavo USB: http://192.168.42.1:8080) apri l\'app **Console**: la libreria della console, con le schede dei giochi. Ogni gioco ha due strade:\n- **Gioca qui**: gira nel browser, col salvataggio del gioco condiviso con la console;\n- **Sulla console**: lo avvia la console, a schermo intero.\nI sistemi pesanti (PSP, NDS, Dreamcast, Saturn) passano dallo streaming **NucleoLink**: li fa girare la console e il browser riceve il video. La prima volta il browser chiede il PIN che mostra la console.',
      en: 'From the browser (same network, or over the USB cable: http://192.168.42.1:8080) open the **Console** app: the console\'s library, with game cards. Every game has two ways:\n- **Play here**: runs in the browser, with the game save shared with the console;\n- **On the console**: the console starts it, full screen.\nHeavy systems (PSP, NDS, Dreamcast, Saturn) go through **NucleoLink** streaming: the console runs them and the browser gets the video. The first time the browser asks for the PIN the console shows.',
      es: 'Desde el navegador (en la misma red, o con el cable USB: http://192.168.42.1:8080) abre la app **Consola**: la biblioteca de la consola, con las fichas de los juegos. Cada juego tiene dos caminos:\n- **Jugar aquí**: corre en el navegador, con la partida compartida con la consola;\n- **En la consola**: lo arranca la consola, a pantalla completa.\nLos sistemas pesados (PSP, NDS, Dreamcast, Saturn) pasan por el streaming **NucleoLink**: los ejecuta la consola y el navegador recibe el vídeo. La primera vez el navegador pide el PIN que muestra la consola.',
      fr: 'Depuis le navigateur (même réseau, ou par le câble USB : http://192.168.42.1:8080) ouvre l\'app **Console** : la bibliothèque de la console, avec les fiches des jeux. Chaque jeu a deux voies :\n- **Jouer ici** : tourne dans le navigateur, avec la sauvegarde partagée avec la console ;\n- **Sur la console** : la console le lance, en plein écran.\nLes systèmes lourds (PSP, NDS, Dreamcast, Saturn) passent par le streaming **NucleoLink** : la console les fait tourner et le navigateur reçoit la vidéo. La première fois, le navigateur demande le PIN affiché par la console.',
      de: 'Im Browser (im selben Netz oder per USB-Kabel: http://192.168.42.1:8080) öffnest du die App **Konsole**: die Bibliothek der Konsole mit den Steckbriefen der Spiele. Jedes Spiel hat zwei Wege:\n- **Hier spielen**: läuft im Browser, mit dem Spielspeicher gemeinsam mit der Konsole;\n- **Auf der Konsole**: die Konsole startet es im Vollbild.\nSchwere Systeme (PSP, NDS, Dreamcast, Saturn) laufen über **NucleoLink**-Streaming: Die Konsole führt sie aus, der Browser bekommt das Video. Beim ersten Mal fragt der Browser nach der PIN, die die Konsole anzeigt.' },
    cards: [{ kind: 'app', arg: 'console', title: 'Console', sub: '' }],
  },
  psp: {
    match: /\b(psp|ppsspp|playstation portable)\b/,
    text: {
      it: '**PSP** gira con PPSSPP dentro RetroArch. Due cose che NucleoOS sistema da sé (`nucleos-emu-tune`, lo applica l\'installatore):\n- i file di PPSSPP vanno nella cartella dei BIOS (`bios/PPSSPP`): senza, il gioco si ferma alla prima finestra di sistema, che resta vuota;\n- prima di ogni avvio NucleoOS toglie un salto di fotogrammi fisso e il limite di FPS che rallentavano alcune console.\nSe un gioco PSP si blocca al primo menu: `sudo nucleos-emu-tune status` dice se i file ci sono, `apply` li rimette. Dal browser i giochi PSP passano dallo streaming NucleoLink.',
      en: '**PSP** runs with PPSSPP inside RetroArch. Two things NucleoOS sets up by itself (`nucleos-emu-tune`, applied by the installer):\n- PPSSPP\'s files go in the BIOS folder (`bios/PPSSPP`): without them the game stops at the first system dialog, which stays empty;\n- before every launch NucleoOS removes a fixed frameskip and an FPS cap that slowed some consoles down.\nIf a PSP game freezes at the first menu: `sudo nucleos-emu-tune status` says whether the files are there, `apply` puts them back. From the browser PSP games go through NucleoLink streaming.',
      es: '**PSP** funciona con PPSSPP dentro de RetroArch. Dos cosas que NucleoOS arregla solo (`nucleos-emu-tune`, lo aplica el instalador):\n- los archivos de PPSSPP van en la carpeta de BIOS (`bios/PPSSPP`): sin ellos el juego se para en el primer diálogo del sistema, que queda vacío;\n- antes de cada arranque NucleoOS quita un salto de fotogramas fijo y un límite de FPS que frenaban algunas consolas.\nSi un juego de PSP se queda en el primer menú: `sudo nucleos-emu-tune status` dice si están los archivos, `apply` los repone. Desde el navegador los juegos de PSP pasan por el streaming NucleoLink.',
      fr: 'La **PSP** tourne avec PPSSPP dans RetroArch. Deux choses que NucleoOS règle tout seul (`nucleos-emu-tune`, appliqué par l\'installateur) :\n- les fichiers de PPSSPP vont dans le dossier des BIOS (`bios/PPSSPP`) : sans eux, le jeu s\'arrête à la première boîte de dialogue système, qui reste vide ;\n- avant chaque lancement, NucleoOS retire un saut d\'images fixe et une limite de FPS qui ralentissaient certaines consoles.\nSi un jeu PSP se bloque au premier menu : `sudo nucleos-emu-tune status` dit si les fichiers sont là, `apply` les remet. Depuis le navigateur, les jeux PSP passent par le streaming NucleoLink.',
      de: '**PSP** läuft mit PPSSPP in RetroArch. Zwei Dinge richtet NucleoOS selbst ein (`nucleos-emu-tune`, vom Installer angewendet):\n- die PPSSPP-Dateien gehören in den BIOS-Ordner (`bios/PPSSPP`): ohne sie bleibt das Spiel beim ersten Systemdialog stehen, der leer bleibt;\n- vor jedem Start entfernt NucleoOS ein festes Frameskip und eine FPS-Grenze, die manche Konsolen bremsten.\nHängt ein PSP-Spiel im ersten Menü: `sudo nucleos-emu-tune status` sagt, ob die Dateien da sind, `apply` legt sie wieder hin. Im Browser laufen PSP-Spiele über NucleoLink-Streaming.' },
  },
  dreamcast: {
    match: /\b(dreamcast|flycast|reicast|dc boot|dc_boot)\b/,
    text: {
      it: '**Dreamcast** gira con Flycast. Il BIOS vero è `dc/dc_boot.bin` nella cartella dei BIOS: alcuni giochi senza non partono con nessun core. Se manca, NucleoOS (`nucleos-emu-tune`) accende il BIOS emulato di Flycast, che basta a molti giochi; se il file c\'è, non lo tocca.\nSu questo hardware il Dreamcast è al limite: il collo di bottiglia è il processore che emula, non la grafica. Abbassare la grafica (salto di fotogrammi, filtri) è stato provato e non aiuta. Dal browser passa dallo streaming NucleoLink.',
      en: '**Dreamcast** runs with Flycast. The real BIOS is `dc/dc_boot.bin` in the BIOS folder: some games won\'t start without it on any core. If it\'s missing, NucleoOS (`nucleos-emu-tune`) turns on Flycast\'s emulated BIOS, which is enough for many games; if the file is there, it leaves it alone.\nOn this hardware Dreamcast is at the limit: the bottleneck is the CPU doing the emulation, not the graphics. Lowering graphics (frameskip, filters) was tested and doesn\'t help. From the browser it goes through NucleoLink streaming.',
      es: '**Dreamcast** funciona con Flycast. La BIOS real es `dc/dc_boot.bin` en la carpeta de BIOS: algunos juegos no arrancan sin ella con ningún core. Si falta, NucleoOS (`nucleos-emu-tune`) activa la BIOS emulada de Flycast, que basta para muchos juegos; si el archivo está, no lo toca.\nEn este hardware la Dreamcast está al límite: el cuello de botella es el procesador que emula, no los gráficos. Bajar los gráficos (salto de fotogramas, filtros) se probó y no ayuda. Desde el navegador pasa por el streaming NucleoLink.',
      fr: 'La **Dreamcast** tourne avec Flycast. Le vrai BIOS est `dc/dc_boot.bin` dans le dossier des BIOS : certains jeux ne démarrent sans lui avec aucun core. S\'il manque, NucleoOS (`nucleos-emu-tune`) active le BIOS émulé de Flycast, qui suffit à beaucoup de jeux ; si le fichier est là, il n\'y touche pas.\nSur ce matériel, la Dreamcast est à la limite : le goulot d\'étranglement est le processeur qui émule, pas les graphismes. Baisser les graphismes (saut d\'images, filtres) a été essayé et n\'aide pas. Depuis le navigateur, elle passe par le streaming NucleoLink.',
      de: '**Dreamcast** läuft mit Flycast. Das echte BIOS ist `dc/dc_boot.bin` im BIOS-Ordner: Manche Spiele starten ohne es mit keinem Core. Fehlt es, schaltet NucleoOS (`nucleos-emu-tune`) das emulierte BIOS von Flycast ein, das für viele Spiele reicht; ist die Datei da, bleibt alles, wie es ist.\nAuf dieser Hardware ist Dreamcast am Limit: Der Engpass ist der emulierende Prozessor, nicht die Grafik. Grafik herunterdrehen (Frameskip, Filter) wurde getestet und hilft nicht. Im Browser läuft es über NucleoLink-Streaming.' },
  },
  usbdisk: {
    match: /\b(disco usb|usb drive|usb disk|disco usb|disque usb|usb laufwerk|lettore di schede|card reader|lector de tarjetas|lecteur de cartes|kartenleser)\b/,
    text: {
      it: '**Disco USB** (scheda Sistema): collega la console al PC con un cavo dati e le schede compaiono sul PC come chiavette: copi ROM, BIOS, musica e film come su un disco. Mentre è attivo la console fa solo da lettore di schede (niente WiFi, il controller USB è uno solo); uscendo torna tutto com\'era.',
      en: '**USB Drive** (System tab): connect the console to the PC with a data cable and the cards show up on the PC like sticks: copy ROMs, BIOS, music and films as on a disk. While it\'s on the console only acts as a card reader (no WiFi: there is a single USB controller); when you leave, everything is back as before.',
      es: '**Disco USB** (pestaña Sistema): conecta la consola al PC con un cable de datos y las tarjetas aparecen en el PC como pendrives: copias ROM, BIOS, música y películas como en un disco. Mientras está activo la consola solo hace de lector de tarjetas (sin WiFi: hay un único controlador USB); al salir todo vuelve a como estaba.',
      fr: '**Disque USB** (onglet Système) : relie la console au PC avec un câble de données et les cartes apparaissent sur le PC comme des clés : tu copies ROM, BIOS, musique et films comme sur un disque. Pendant ce temps, la console sert seulement de lecteur de cartes (pas de WiFi : il n\'y a qu\'un contrôleur USB) ; en sortant, tout redevient comme avant.',
      de: '**USB-Laufwerk** (Reiter System): Verbinde die Konsole per Datenkabel mit dem PC, und die Karten erscheinen am PC wie Sticks: ROMs, BIOS, Musik und Filme kopierst du wie auf eine Festplatte. Solange es aktiv ist, ist die Konsole nur Kartenleser (kein WLAN: es gibt nur einen USB-Controller); beim Verlassen ist alles wieder wie vorher.' },
  },
  joypad: {
    match: /\b(joypad|controller per (il )?pc|pad per (il )?pc|gamepad for (the )?pc|use (the )?console as (a )?(controller|gamepad)|mando para (el )?pc|manette pour (le )?pc|controller fur den pc|xbox)\b/,
    text: {
      it: '**Joypad** (scheda Sistema): la console diventa un pad Xbox per il PC. Col cavo USB il WiFi va spento; via WiFi serve il piccolo programma `nucleo-pad-agent` sul PC. Il contrario, cioè usare la console per comandare un\'app web, è **NucleoPad**: lo chiede l\'app nel browser e la console mostra una schermata di consenso.',
      en: '**Joypad** (System tab): the console becomes an Xbox pad for the PC. Over the USB cable WiFi must be off; over WiFi the small `nucleo-pad-agent` program is needed on the PC. The other way round, using the console to drive a web app, is **NucleoPad**: the app in the browser asks for it and the console shows a consent screen.',
      es: '**Joypad** (pestaña Sistema): la consola se convierte en un mando Xbox para el PC. Con el cable USB el WiFi tiene que estar apagado; por WiFi hace falta el pequeño programa `nucleo-pad-agent` en el PC. Lo contrario, usar la consola para manejar una app web, es **NucleoPad**: lo pide la app en el navegador y la consola muestra una pantalla de consentimiento.',
      fr: '**Joypad** (onglet Système) : la console devient une manette Xbox pour le PC. Par câble USB le WiFi doit être coupé ; par WiFi il faut le petit programme `nucleo-pad-agent` sur le PC. L\'inverse, piloter une app web avec la console, c\'est **NucleoPad** : l\'app dans le navigateur le demande et la console affiche un écran de consentement.',
      de: '**Joypad** (Reiter System): Die Konsole wird zum Xbox-Pad für den PC. Per USB-Kabel muss das WLAN aus sein; per WLAN braucht der PC das kleine Programm `nucleo-pad-agent`. Umgekehrt, eine Web-App mit der Konsole steuern, ist **NucleoPad**: Die App im Browser fragt danach, und die Konsole zeigt einen Zustimmungsbildschirm.' },
  },
  stats: {
    match: /\b(statistiche|statistics|estadisticas|statistiques|statistik\w*)\b(?!.*\b(gioc\w*|game|juego|jeu|spiel)\b)/,
    text: {
      it: 'La tessera **Statistiche** (scheda Giochi) mostra il tempo di gioco e i giochi più giocati sulla console. Chiedimi anche «quanto ho giocato?» o «quanto ho giocato a …».',
      en: 'The **Statistics** tile (Games tab) shows play time and top games on the console. You can also ask me “how long have I played?” or “how long have I played …”.',
      es: 'La casilla **Estadísticas** (pestaña Juegos) muestra el tiempo de juego y los juegos más jugados en la consola. Pregúntame también «¿cuánto he jugado?» o «¿cuánto he jugado a …?».',
      fr: 'La tuile **Statistiques** (onglet Jeux) montre le temps de jeu et les jeux les plus joués sur la console. Tu peux aussi me demander « combien j\'ai joué ? » ou « combien j\'ai joué à … ».',
      de: 'Die Kachel **Statistik** (Reiter Spiele) zeigt Spielzeit und meistgespielte Spiele auf der Konsole. Frag mich auch „wie lange habe ich gespielt?“ oder „wie lange habe ich … gespielt?“.' },
  },
  guide: {
    match: /\b(guida|manuale|istruzioni|tutorial|guide|manual|handbook|instrucciones|guia|mode d emploi|anleitung|handbuch|hilfe)\b.*\b(nucleoos|console|consola|konsole|sistema|system|systeme)\b|\bcosa (sai|puoi) fare\b|\bwhat can you do\b|\bque puedes hacer\b|\bque sais tu faire\b|\bwas kannst du\b/,
    text: {
      it: 'Per il gioco posso:\n- **giocare**: «gioca a Zelda», «cosa gioco?», «un gioco di corse in due», «a cosa sto giocando?»;\n- **la tua storia**: «quanto ho giocato?», «di cosa parla Metroid?», «i salvataggi di Pokémon»;\n- **trucchi**: «trucchi per Contra», «attiva il trucco vite infinite in Contra»;\n- **creare giochi** per la console: «crea un gioco: schiva gli asteroidi», poi «aggiungi un boss». Lo scrivo, lo installo, lo provo sulla console e lo correggo da sola;\n- **la console**: «mi manca qualche BIOS?», «che emulatore usa la SNES?», «quali port ho?», «cosa non va?»;\n- **come si fa**: tasti durante il gioco, Continua, RetroAchievements, netplay, PortMaster, PSP, Dreamcast, Disco USB.\nSulla console c\'è anche la **Guida** (scheda Sistema), con R che la legge tutta di fila.',
      en: 'For gaming I can:\n- **play**: “play Zelda”, “what should I play?”, “a racing game for two”, “what am I playing?”;\n- **your history**: “how long have I played?”, “what is Metroid about?”, “saves of Pokémon”;\n- **cheats**: “cheats for Contra”, “enable the infinite lives cheat in Contra”;\n- **make games** for the console: “create a game: dodge the asteroids”, then “add a boss”. I write it, install it, test it on the console and fix it myself;\n- **the console**: “am I missing any BIOS?”, “which emulator does the SNES use?”, “which ports do I have?”, “what\'s wrong?”;\n- **how-to**: in-game buttons, Continue, RetroAchievements, netplay, PortMaster, PSP, Dreamcast, USB Drive.\nOn the console there is also the **Guide** (System tab); R reads it all in a row.',
      es: 'Para jugar puedo:\n- **jugar**: «juega a Zelda», «¿a qué juego?», «un juego de carreras a dos», «¿a qué estoy jugando?»;\n- **tu historial**: «¿cuánto he jugado?», «¿de qué va Metroid?», «partidas de Pokémon»;\n- **trucos**: «trucos de Contra», «activa el truco vidas infinitas en Contra»;\n- **crear juegos** para la consola: «crea un juego: esquiva los asteroides», luego «añade un jefe». Lo escribo, lo instalo, lo pruebo en la consola y lo corrijo yo sola;\n- **la consola**: «¿me falta alguna BIOS?», «¿qué emulador usa la SNES?», «¿qué ports tengo?», «¿hay algún problema?»;\n- **cómo se hace**: botones en el juego, Continuar, RetroAchievements, netplay, PortMaster, PSP, Dreamcast, Disco USB.\nEn la consola también está la **Guía** (pestaña Sistema); R la lee entera seguida.',
      fr: 'Pour le jeu, je peux :\n- **jouer** : « joue à Zelda », « à quoi jouer ? », « un jeu de course à deux », « à quoi je joue ? » ;\n- **ton historique** : « combien j\'ai joué ? », « de quoi parle Metroid ? », « sauvegardes de Pokémon » ;\n- **codes de triche** : « codes de triche pour Contra », « active le code vies infinies dans Contra » ;\n- **créer des jeux** pour la console : « crée un jeu : esquive les astéroïdes », puis « ajoute un boss ». Je l\'écris, je l\'installe, je le teste sur la console et je le corrige toute seule ;\n- **la console** : « il me manque un BIOS ? », « quel émulateur utilise la SNES ? », « quels ports j\'ai ? », « y a-t-il des problèmes ? » ;\n- **comment faire** : boutons en jeu, Continuer, RetroAchievements, netplay, PortMaster, PSP, Dreamcast, Disque USB.\nSur la console il y a aussi le **Guide** (onglet Système) ; R le lit en entier.',
      de: 'Beim Spielen kann ich:\n- **spielen**: „spiele Zelda“, „was soll ich spielen?“, „ein Rennspiel zu zweit“, „was spiele ich gerade?“;\n- **deine Geschichte**: „wie lange habe ich gespielt?“, „worum geht es in Metroid?“, „Spielstände von Pokémon“;\n- **Cheats**: „Cheats für Contra“, „aktiviere den Cheat unendliche Leben in Contra“;\n- **Spiele erstellen** für die Konsole: „erstelle ein Spiel: weiche den Asteroiden aus“, dann „füge einen Boss hinzu“. Ich schreibe es, installiere es, teste es auf der Konsole und behebe Fehler selbst;\n- **die Konsole**: „fehlt mir ein BIOS?“, „welchen Emulator nutzt das SNES?“, „welche Ports habe ich?“, „gibt es Probleme?“;\n- **wie es geht**: Tasten im Spiel, Fortsetzen, RetroAchievements, Netplay, PortMaster, PSP, Dreamcast, USB-Laufwerk.\nAuf der Konsole gibt es auch die **Anleitung** (Reiter System); R liest sie am Stück vor.' },
  },
};

// L'ordine conta: la prima voce che risponde vince. Le più specifiche prima (PortMaster prima di Ports,
// PSP/Dreamcast prima delle domande generiche sui giochi).
const ORDER = ['portmaster', 'psp', 'dreamcast', 'ra', 'netplay', 'lowbat', 'hotkeys', 'resume', 'quick', 'emulator', 'scrape',
               'favorites', 'browser', 'usbdisk', 'joypad', 'stats', 'ports', 'guide'];

// Una voce nella lingua: { text, cards }. Lingua sconosciuta -> inglese.
export function entry(id, lang) {
  const e = KB[id];
  if (!e) return null;
  return { text: e.text[lang] || e.text.en, cards: e.cards ? e.cards.map((c) => Object.assign({}, c)) : undefined };
}

export function matchKb(q) {
  const f = fold(q);
  if (!f) return null;
  for (const id of ORDER) if (KB[id].match && KB[id].match.test(f)) return id;
  return null;
}

export function answer(q, lang) {
  const id = matchKb(q);
  if (!id) return null;
  const e = entry(id, lang);
  return { reply: e.text, tier: 'command', action: 'answer', intent: 'howto:' + id, domain: 'console',
           confidence: 85, local: true, skill: true, trace: 'NucleoOS · guida', cards: e.cards };
}

// Il manuale per i modelli: gli stessi fatti, in inglese e compatti. Il modello risponde nella lingua
// dell'utente; qui gli si dice COSA è vero su questa console, così non inventa menu che non esistono.
export function handbook() {
  return [
    'NucleoOS gaming facts (true for this console; never invent other menus or buttons):',
    '- In game, hold SELECT and press: START = back to the NucleoOS menu, R = save state, L = load state, X = RetroArch menu, Y = screenshot. There is NO in-game combo for fast-forward, volume or brightness.',
    '- Leaving a game always writes an automatic state; "Continue" (systems list, or Y then X on a game) resumes it. A copy of the save is kept before and after every session; restore it from the game: Y, START, Saves (or the Console web app).',
    '- On a game: A plays, X favourite, Y opens its panel (left/right = per-game emulator core, L = host netplay, R = join netplay, X = continue, START = edit: name, genre, year, rating, hidden, emulator options, Cheats, Saves; SELECT = custom collections).',
    '- Systems list, Y menu: Emulator (core per system), Emulator options, Audio, BIOS check, Scrape, Scrape all, RetroAchievements login, RA hardcore. START = search all systems. Holding SELECT in menus opens the Quick Center.',
    '- Cheats: official libretro database (~37 MB, downloaded once), applied by RetroArch on the console from the next game start; not in the browser player; hardcore mode blocks them. ANIMA can list, enable and disable them.',
    '- Ports: .sh scripts in the ports/ folder of the games card, launched from the Ports tile; PortMaster tile installs and updates ports (needs WiFi). Install-NucleoOS and NucleoOS-Canale-SD are NucleoOS\'s own ports.',
    '- PSP: PPSSPP in RetroArch; needs PPSSPP assets in bios/PPSSPP (nucleos-emu-tune puts them there). Dreamcast: Flycast; dc/dc_boot.bin in bios, otherwise the emulated BIOS is enabled; the CPU is the bottleneck, lowering graphics does not help. PSP, NDS, Dreamcast and Saturn stream to the browser via NucleoLink.',
    '- Below 5% battery during a game NucleoOS quits it cleanly (state saved) and powers off. RetroAchievements: login from the systems list Y menu (password swapped for a token, never stored).',
    '- ANIMA CREATES games for this console (LÖVE 11.4 / Lua, the Love2d system): "create a game …" writes it, installs it, TESTS it on the console (6 s run, screenshot, error log) and fixes it until it runs; "add …" changes the last one. Point users there instead of writing game code in the chat.',
    '- ROMs go in roms/<system>/ on the games card (File app, USB Drive mode, or the card in a PC). BIOS files go in the bios folder; ANIMA can say which ones are missing.',
  ].join('\n');
}
